 16→/// Canonical Silver dataset identifiers.
 17→///
 18→/// These correspond to the seven Silver datasets defined in
 19→/// V2_ARCHITECTURE_RFC Section 3.5. Each variant maps to a normalized
 20→/// table or logical dataset produced from Bronze raw data.
 21→#[derive(
 22→    Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, Display, EnumString, EnumIter,
 23→)]
 24→#[serde(rename_all = "snake_case")]
 25→#[strum(serialize_all = "snake_case")]
 26→pub enum DatasetName {
 27→    /// Financial ledger for tax/portfolio (existing Silver dataset).
 28→    LedgerEntries,
