 30→    TokenTransfers,
 31→    /// Native currency balance changes per account per transaction.
 32→    NativeBalanceDeltas,
 33→    /// ABI-decoded EVM events and Solana instruction logs.
 34→    DecodedEvents,
 35→    /// Hyperliquid fill records.
 36→    HlFills,
 37→    /// Hyperliquid funding payments.
 38→    HlFunding,
 39→    /// Position state changes derived from fills, funding, liquidations.
 40→    Positions,
 41→}
 42→
 43→impl DatasetName {
 44→    /// Returns the SQL-compatible string for this dataset name.
