 75→/// Metadata describing a Silver dataset's purpose and lineage.
 76→#[derive(Debug, Clone, Serialize, Deserialize)]
 77→pub struct DatasetDescriptor {
 78→    /// Canonical dataset identifier.
 79→    pub name: DatasetName,
 80→    /// Human-readable description.
 81→    pub description: String,
 82→    /// Bronze tables this dataset derives from.
 83→    pub source_bronze_tables: Vec<String>,
