102→// ---------------------------------------------------------------------------
103→// Materializer Trait
104→// ---------------------------------------------------------------------------
105→
106→/// Trait for parser/materializer version tracking.
107→///
108→/// Each chain-specific parser that produces Silver data implements this trait
109→/// to declare its identity and version. This enables:
110→/// - safe reprocessing when parser logic changes
111→/// - dataset version linkage for provenance tracking
112→/// - regeneration decisions based on version comparison
113→pub trait Materializer: Send + Sync {
114→    /// The canonical dataset this materializer produces.
115→    fn dataset_name(&self) -> DatasetName;
116→
117→    /// Monotonically increasing parser version number.
118→    /// Increment this when the parser logic changes.
119→    fn parser_version(&self) -> i32;
120→
121→    /// Stable content hash of the parser logic.
122→    /// This should change whenever the parser behavior changes,
123→    /// enabling detection of unreleased changes during development.
124→    fn parser_hash(&self) -> &str;
125→
126→    /// The chain family this materializer serves.
