137→/// Scope of a regeneration request — which data to reprocess.
138→#[derive(Debug, Clone, Serialize, Deserialize)]
139→pub struct RegenerationScope {
140→    /// Dataset to regenerate.
141→    pub dataset: DatasetName,
142→    /// Optional target ID to scope regeneration.
143→    /// When `None`, regenerates across all targets.
144→    pub target_id: Option<uuid::Uuid>,
145→    /// Optional time range to scope regeneration.
146→    /// Both bounds are inclusive Unix timestamps.
147→    pub time_range: Option<(i64, i64)>,
148→}
149→
150→impl RegenerationScope {
151→    /// Validate the scope. If a time range is provided, start must be <= end.
152→    pub fn validate(&self) -> Result<(), String> {
153→        if let Some((start, end)) = self.time_range {
154→            if start > end {
155→                return Err(format!(
156→                    "RegenerationScope time_range start ({start}) must be <= end ({end})"
157→                ));
158→            }
159→        }
160→        Ok(())
161→    }
162→}
