 213→/// Build a batch INSERT for `raw_transactions` with ON CONFLICT DO NOTHING.
 214→pub fn build_raw_transaction_insert(
 215→    txs: &[RawTransaction],
 216→) -> anyhow::Result<(String, sqlx::postgres::PgArguments)> {
 217→    let mut query = String::from(
 218→        "INSERT INTO raw_transactions \
 219→         (id, network, tx_hash, timestamp, block_number, raw_metadata, source, ingestion_run_id, ingested_at) \
 220→         VALUES ",
 221→    );
 222→    let mut args = sqlx::postgres::PgArguments::default();
 223→    for (i, tx) in txs.iter().enumerate() {
 224→        let base = i * 9;
 225→        if i > 0 {
 226→            query.push_str(", ");
 227→        }
 228→        query.push_str(&format!(
 229→            "(${}, ${}, ${}, ${}, ${}, ${}, ${}, ${}, ${})",
 230→            base + 1,
 231→            base + 2,
 232→            base + 3,
 233→            base + 4,
 234→            base + 5,
 235→            base + 6,
 236→            base + 7,
 237→            base + 8,
 238→            base + 9,
 239→        ));
 240→        use sqlx::Arguments;
 241→        args.add(tx.id).map_err(|e| anyhow::anyhow!("{e}"))?;
 242→        args.add(&tx.network).map_err(|e| anyhow::anyhow!("{e}"))?;
 243→        args.add(&tx.tx_hash).map_err(|e| anyhow::anyhow!("{e}"))?;
 244→        args.add(tx.timestamp).map_err(|e| anyhow::anyhow!("{e}"))?;
 245→        args.add(tx.block_number)
 246→            .map_err(|e| anyhow::anyhow!("{e}"))?;
 247→        args.add(&tx.raw_metadata)
 248→            .map_err(|e| anyhow::anyhow!("{e}"))?;
 249→        args.add(&tx.source).map_err(|e| anyhow::anyhow!("{e}"))?;
 250→        args.add(tx.ingestion_run_id)
 251→            .map_err(|e| anyhow::anyhow!("{e}"))?;
 252→        args.add(tx.ingested_at)
 253→            .map_err(|e| anyhow::anyhow!("{e}"))?;
 254→    }
 255→    query.push_str(" ON CONFLICT (network, tx_hash) DO NOTHING");
 256→    Ok((query, args))
 257→}
