 377→/// Build the INSERT for a single `dataset_version`.
 378→pub fn build_dataset_version_insert(
 379→    dv: &DatasetVersion,
 380→) -> anyhow::Result<(String, sqlx::postgres::PgArguments)> {
 381→    let query = String::from(
 382→        "INSERT INTO dataset_versions (id, dataset_name, version, parser_hash, created_at, notes, status) \
 383→         VALUES ($1, $2, $3, $4, $5, $6, $7)",
 384→    );
 385→    let mut args = sqlx::postgres::PgArguments::default();
 386→    use sqlx::Arguments;
 387→    args.add(dv.id).map_err(|e| anyhow::anyhow!("{e}"))?;
 388→    args.add(&dv.dataset_name)
 389→        .map_err(|e| anyhow::anyhow!("{e}"))?;
 390→    args.add(dv.version).map_err(|e| anyhow::anyhow!("{e}"))?;
 391→    args.add(&dv.parser_hash)
 392→        .map_err(|e| anyhow::anyhow!("{e}"))?;
 393→    args.add(dv.created_at)
 394→        .map_err(|e| anyhow::anyhow!("{e}"))?;
 395→    args.add(&dv.notes).map_err(|e| anyhow::anyhow!("{e}"))?;
 396→    args.add(dataset_version_status_to_sql(&dv.status))
 397→        .map_err(|e| anyhow::anyhow!("{e}"))?;
 398→    Ok((query, args))
