 593→    pub async fn get_matches_by_target(
 594→        &self,
 595→        target_id: Uuid,
 596→        limit: i64,
 597→        offset: i64,
 598→    ) -> anyhow::Result<Vec<(TargetMatch, RawTransaction)>> {
 599→        let rows = sqlx::query(
 600→            "SELECT \
 601→                 tm.id, tm.target_id, tm.raw_transaction_id, tm.match_reason, tm.matched_at, \
 602→                 rt.id AS rt_id, rt.network, rt.tx_hash, rt.timestamp, rt.block_number, \
 603→                 rt.raw_metadata, rt.source, rt.ingestion_run_id, rt.ingested_at \
 604→             FROM target_matches tm \
 605→             JOIN raw_transactions rt ON rt.id = tm.raw_transaction_id \
 606→             WHERE tm.target_id = $1 \
 607→             ORDER BY rt.timestamp DESC \
 608→             LIMIT $2 OFFSET $3",
 609→        )
 610→        .bind(target_id)
 611→        .bind(limit)
 612→        .bind(offset)
 613→        .fetch_all(self.pool())
 614→        .await?;
 615→
 616→        let mut results = Vec::with_capacity(rows.len());
 617→        for row in &rows {
 618→            let tm = TargetMatch {
 619→                id: row.try_get("id")?,
 620→                target_id: row.try_get("target_id")?,
 621→                raw_transaction_id: row.try_get("raw_transaction_id")?,
 622→                match_reason: row.try_get("match_reason")?,
 623→                matched_at: row.try_get("matched_at")?,
 624→            };
 625→            let rt = RawTransaction {
 626→                id: row.try_get("rt_id")?,
 627→                network: row.try_get("network")?,
 628→                tx_hash: row.try_get("tx_hash")?,
 629→                timestamp: row.try_get("timestamp")?,
 630→                block_number: row.try_get("block_number")?,
 631→                raw_metadata: row.try_get("raw_metadata")?,
 632→                source: row.try_get("source")?,
 633→                ingestion_run_id: row.try_get("ingestion_run_id")?,
 634→                ingested_at: row.try_get("ingested_at")?,
 635→            };
 636→            results.push((tm, rt));
 637→        }
 638→        Ok(results)
 639→    }
