        let desc = DatasetDescriptor {
            name: DatasetName::TokenTransfers,
            description: "Token transfers".to_string(),
            source_bronze_tables: vec![],
            chain_families: vec![ChainFamily::Evm],
        };
        assert!(desc.validate().is_err());
    }

