        let entries2 = parse_evm_transaction(&tx).unwrap();

        assert_eq!(entries1.len(), entries2.len());
        for (a, b) in entries1.iter().zip(entries2.iter()) {
            assert_eq!(a.id, b.id);
        }
    }
