            "gas_used": "0x5208",
            "effective_gas_price": "0x3b9aca00",
        }));
        let entries1 = parse_evm_transaction(&tx).unwrap();
        let entries2 = parse_evm_transaction(&tx).unwrap();

        assert_eq!(entries1.len(), entries2.len());
