            .map_err(|e| anyhow::anyhow!("{e}"))?;
        args.add(d.dataset_version_id)
            .map_err(|e| anyhow::anyhow!("{e}"))?;
        args.add(d.created_at)
            .map_err(|e| anyhow::anyhow!("{e}"))?;
    }
    query.push_str(
        " ON CONFLICT (raw_transaction_id, account_address) \
         WHERE raw_transaction_id IS NOT NULL DO NOTHING",
    );
    Ok((query, args))
}

